import json, os

BASE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.join(BASE, 'data', 'database_v2.json')
os.makedirs(os.path.join(BASE, 'data', 'v1'), exist_ok=True)
os.makedirs(os.path.join(BASE, 'data', 'v2'), exist_ok=True)
