OUT_V2 = os.path.join(BASE, 'data', 'v2', 'database.json')

def norm(rec):
    out = {}
    for k, v in rec.items():
        key = str(k).strip()
        out[key] = v.strip() if isinstance(v, str) else v
    return out

raw = json.load(open(SRC, encoding='utf-8'))
db = [norm(r) for r in raw]

if not os.path.exists(OUT_V1):
    json.dump(db, open(OUT_V1, 'w', encoding='utf-8'), ensure_ascii=False, indent=2)
    print('V1 salvata (stato pre-audit):', OUT_V1)

